select *, sum(quantity) over (partition by store_id order by last_restock, id rows between unbounded preceding and current row) as running_quantity, ntile(3) over (partition by product_id, store_id order by quantity, id) as quantity_bucket, last_value(quantity, true) over (partition by product_id order by last_restock, id rows between unbounded preceding and current row) as last_known_quantity, ntile(3) over (partition by product_id order by quantity, id) as quantity_bucket_2 from inventory;
